IF XACT_STATE()<>0 ROLLBACK; SET TRANSACTION ISOLATION LEVEL READ COMMITTED; DECLARE @B bigint=?; IF @B>0 BEGIN UPDATE etl.ETL_LoadBatch SET Status='FAILED',ValidationStatus='FAILED',LoadCompletedAt=SYSUTCDATETIME(),ErrorMessage='SSIS Data Flow failed; all target/raw/watermark writes rolled back. See Progress log.' WHERE LoadBatchID=@B AND Status='RUNNING'; UPDATE etl_v2.BatchState SET Status='FAILED',ErrorMessage='SSIS Data Flow rollback; see package log' WHERE BatchID=@B AND Status='RUNNING'; END; IF APPLOCK_MODE('public','InventorySafety_FullLoad','Session')<>'NoLock' EXEC sys.sp_releaseapplock @Resource='InventorySafety_FullLoad',@LockOwner='Session'; IF APPLOCK_MODE('public','DSS_RESULT','Session')<>'NoLock' EXEC sys.sp_releaseapplock @Resource='DSS_RESULT',@LockOwner='Session';